"""
验证 OpenAI 产品与模型历史时间线的数据规模、字段契约、日期边界、官方来源及关键节点覆盖。
"""

from __future__ import annotations

import json
import unittest
from datetime import date
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parents[1]
DATA_PATH = ROOT / "work" / "timeline-data.json"
REQUIRED = {
    "date", "precision", "category", "track", "family", "title", "summary",
    "delta", "optimization", "availability", "significance", "sourceLabel",
    "sourceUrl", "autoGenerated", "verification",
}
ALLOWED_HOSTS = {
    "openai.com", "www.openai.com", "help.openai.com", "developers.openai.com",
    "platform.openai.com", "learn.chatgpt.com", "twitter.com", "x.com",
}


class TimelineDataTest(unittest.TestCase):
    """保证历史数据具备全景规模且可被构建器稳定消费。"""

    @classmethod
    def setUpClass(cls) -> None:
        cls.data = json.loads(DATA_PATH.read_text(encoding="utf-8"))
        cls.events = cls.data["events"]

    def test_timeline_has_panorama_scale_and_full_range(self) -> None:
        self.assertGreaterEqual(len(self.events), 100)
        self.assertLessEqual(self.events[0]["date"], "2015-12-31")
        self.assertEqual(self.data["cutoff"], "2026-10-20")
        self.assertLessEqual(self.events[-1]["date"], self.data["cutoff"])

    def test_every_event_matches_contract_and_order(self) -> None:
        previous = date.min
        for event in self.events:
            with self.subTest(title=event.get("title")):
                self.assertTrue(REQUIRED <= event.keys())
                current = date.fromisoformat(event["date"])
                self.assertGreaterEqual(current, previous)
                self.assertLessEqual(current, date.fromisoformat(self.data["cutoff"]))
                previous = current
                self.assertIn(event["verification"], {"人工整理", "自动收录", "页面变更"})

    def test_every_source_is_official_https(self) -> None:
        for event in self.events:
            parsed = urlparse(event["sourceUrl"])
            with self.subTest(url=event["sourceUrl"]):
                self.assertEqual(parsed.scheme, "https")
                self.assertIn(parsed.hostname, ALLOWED_HOSTS)

    def test_required_tracks_are_covered(self) -> None:
        tracks = {event["track"] for event in self.events}
        expected = {"技术基础", "模型体系", "ChatGPT 产品", "API / Agents", "Codex", "多模态", "订阅计划", "迁移与治理"}
        self.assertTrue(expected <= tracks)

    def test_representative_milestones_are_covered(self) -> None:
        corpus = " ".join(event["title"] + " " + event["summary"] for event in self.events)
        expected = (
            "GPT-1", "GPT-2", "GPT-3", "InstructGPT", "ChatGPT", "GPT-4", "GPT-4o",
            "o1", "GPT-5", "GPT-6", "DALL·E", "Whisper", "Sora", "Codex",
            "Responses API", "ChatGPT Plus", "Enterprise", "Deep Research", "ChatGPT Agent",
            "GPT-6.1 Sol", "Intelligent UI",
        )
        for phrase in expected:
            with self.subTest(phrase=phrase):
                self.assertIn(phrase, corpus)


if __name__ == "__main__":
    unittest.main()
